/// <summary>
/// Gets/sets the SO this task processes.
/// </summary>
/// <param name = "_salesId">Sales order to process</param>
/// <returns>The current SalesId</returns>
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;
    return salesId;
}

/// <summary>
/// Gets/sets the CSD SalesId used for wave/print-mode checks.
/// </summary>
/// <param name = "_csdSalesId">CSD sales order id</param>
/// <returns>The current CSD SalesId</returns>
public SalesId parmCSDSalesId(SalesId _csdSalesId = csdSalesId)
{
    csdSalesId = _csdSalesId;
    return csdSalesId;
}

/// <summary>
/// Gets/sets the CSD extract datetime, used for the wave lookup on the End task.
/// </summary>
/// <param name = "_csdOrderExtractDateTime">CSD extract datetime</param>
/// <returns>The current value</returns>
public utcdatetime parmCSDSalesOrderExtractDateTime(utcdatetime _csdOrderExtractDateTime = csdOrderExtractDateTime)
{
    csdOrderExtractDateTime = _csdOrderExtractDateTime;
    return csdOrderExtractDateTime;
}

/// <summary>
/// Gets/sets the CSD order count passed to wave creation.
/// </summary>
/// <param name = "_csdSalesOrderCount">CSD order count</param>
/// <returns>The current value</returns>
public RefRecId parmCSDSalesOrderCount(RefRecId _csdSalesOrderCount = csdSalesOrderCount)
{
    csdSalesOrderCount = _csdSalesOrderCount;
    return csdSalesOrderCount;
}

/// <summary>
/// Gets/sets the staging-lane continuation flag.
/// </summary>
/// <param name = "_continueFromStagingLane">Staging-lane continuation flag</param>
/// <returns>The current value</returns>
public boolean parmContinueFromStagingLane(boolean _continueFromStagingLane = continueFromStagingLane)
{
    continueFromStagingLane = _continueFromStagingLane;
    return continueFromStagingLane;
}

/// <summary>
/// Gets/sets the CSD wave GUID.
/// </summary>
/// <param name = "_csdGuid">CSD wave GUID</param>
/// <returns>The current value</returns>
public str parmCsdGuid(str _csdGuid = csdGuid)
{
    csdGuid = _csdGuid;
    return csdGuid;
}

/// <summary>
/// Gets/sets the full CSD SO list for this extraction.
/// </summary>
/// <param name = "_csdSalesOrderList">CSD SalesIds</param>
/// <returns>The current value</returns>
public container parmCSDSalesOrderList(container _csdSalesOrderList = csdSalesOrderList)
{
    csdSalesOrderList = _csdSalesOrderList;
    return csdSalesOrderList;
}

/// <summary>
/// Gets/sets the owning ExtractionId.
/// </summary>
/// <param name = "_extractionId">Owning ExtractionId</param>
/// <returns>The current value</returns>
public METSalesOrderExtractionId parmSalesOrderExtractionId(METSalesOrderExtractionId _extractionId = extractionId)
{
    extractionId = _extractionId;
    return extractionId;
}

/// <summary>
/// Gets/sets the shipment ids to clean up on the End task.
/// </summary>
/// <param name = "_shipmentIdList">Shipment ids for this extraction</param>
/// <returns>The current value</returns>
public container parmShipmentIdList(container _shipmentIdList = shipmentIdList)
{
    shipmentIdList = _shipmentIdList;
    return shipmentIdList;
}

/// <summary>
/// Packs batchIdentifier (base class) plus this class's own fields.
/// </summary>
/// <returns>Packed state</returns>
public container pack()
{
    return [#CurrentVersion, #CurrentList, super()];
}

/// <summary>
/// Reverses pack().
/// </summary>
/// <param name = "_packedClass">Packed state produced by pack()</param>
/// <returns>True if the packed version was recognized</returns>
public boolean unpack(container _packedClass)
{
    Version   version = RunBase::getVersion(_packedClass);
    container baseCon;

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, baseCon] = _packedClass;
            super(baseCon);
            break;
        default:
            return false;
    }
    return true;
}

/// <summary>
/// Static fallback caption; per-task captions come from caption() instead.
/// </summary>
/// <returns>The fallback caption</returns>
public static ClassDescription description()
{
    return "@MET:MetPickingListGenerationTask";
}

/// <summary>
/// Per-SO pick list posting, wrapped with the standard retry/error handling and
/// extraction-line status update.
/// </summary>
protected void runThreadTask()
{
    #OCCRetryCount
    boolean phase2HasError;

    try
    {
        batchTransactionCommit = METCustParameters::find().SalesExtractionBatchTransactionCommit;
        this.processPickingListPhase2();
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                phase2HasError = true;
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch(Exception::DuplicateKeyException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                phase2HasError = true;
                throw Exception::DuplicateKeyExceptionNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::DuplicateKeyException;
        }
    }
    catch (Exception::Error)
    {
        str errorMessage;
        SysInfologEnumerator enumerator;
        SysInfologMessageStruct msgStruct;

        phase2HasError = true;

        enumerator = SysInfologEnumerator::newData(infolog.copy(1, infologLine()));
        while (enumerator.moveNext())
        {
            msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
            errorMessage += msgStruct.message() + " ";
        }

        if (salesId != '')
        {
            METTelemetrySOExtractionErrorEvent::runTelemetryEvent(salesId, errorMessage);
        }

        this.updateExtractionLineStatus(METSalesOrderExtractionStatus::Failed, errorMessage);
    }
    catch
    {
        phase2HasError = true;
        exceptionTextFallThrough();
    }
    finally
    {
        this.resetProcessingFlag(salesId);

        if (!phase2HasError)
        {
            this.updateExtractionLineStatus(METSalesOrderExtractionStatus::Completed, '');
        }
    }
}

/// <summary>
/// Header-level TMS trigger for substituted lines, wave creation, then branches by ActionToPerform.
/// </summary>
private void processPickingListPhase2()
{
    salesTable      = SalesTable::find(salesId);
    metSalesTable   = METSalesTable::findByRefRecId(salesTable.RecId);

    if (METSalesOrderExtractionLine::IsLineSubstituted(extractionId, salesId))
    {
        ttsbegin;

        if (metSalesTable)
        {
            metSalesTable.selectForUpdate(true);
            metSalesTable.OrderProcessingStatus = METSalesOrderProcessingStatus::ReadyForPricing;
            metSalesTable.update();
            metSalesTable.reread();
        }

        METTMSEngineOrderProccess  METTMSEngineOrderProccess = METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::SalesOrderCreation, salesTable);
        METTMSEngineOrderProccess.run();

        ttscommit;
    }

    if (salesTable)
    {
        inventParameter = InventParameters::find();
        inventLocation  = InventLocation::find(salesTable.InventLocationId);

        if (this.isWaveRequired(salesTable, inventLocation))
        {
            salesTable.createWaveFromSalesTable(inventLocation.METPickDirector, csdSalesOrderCount, csdGuid);
        }

        actionToPerform = this.readStoredActionToPerform(extractionId, salesTable.SalesId);

        switch (actionToPerform)
        {
            case METConstants::SOExtractCreateOnlyTO:
                this.insertPendingProcessRecord(salesTable.SalesId);
                break;

            case METConstants::SOExtractReservedSOPickAndTO:
            case METConstants::SOExtractReservedSOPickOnly:
                this.postPickingListV2(salesTable);
                this.postIntercompanyPickingList();
                break;

            case METConstants::SOExtractOrderedSOPickOnly:
                this.postPickingListV2(salesTable, true);
                this.postIntercompanyPickingList();
                break;

            case METConstants::SOExtractUpdateStatusOnly:
                this.updateStatusOnlyForSalesTable();
                break;

            case METConstants::SOExtractSkip:
                warning(strFmt("@MET:NoActionSOExtract", salesTable.SalesId));
                break;
        }
    }
}

/// <summary>
/// True if the SO was CSD-stamped and the warehouse requires waving.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
/// <param name = "_inventLocation">The order's warehouse</param>
/// <returns>True if a wave should be created</returns>
private boolean isWaveRequired(SalesTable _salesTable, InventLocation _inventLocation)
{
    boolean ret = false;

    if (_salesTable.salesid && DateTimeUtil::minValue() != _salesTable.METOrderExtractDateTime
            && _inventLocation.METWaveRequired == NoYes::Yes)
    {
        ret = true;
    }

    return ret;
}

/// <summary>
/// Reads back the ActionToPerform stamped by Phase 1.
/// </summary>
/// <param name = "_extractionId">Owning ExtractionId</param>
/// <param name = "_salesId">Sales order to look up</param>
/// <returns>The stored action code</returns>
private str readStoredActionToPerform(METSalesOrderExtractionId _extractionId, SalesId _salesId)
{
    METSalesOrderExtractionLine extractionLine = METSalesOrderExtractionLine::find(_extractionId, _salesId);

    return extractionLine.ActionToPerform;
}

/// <summary>
/// Records this SO's pick-list outcome on its extraction line.
/// </summary>
/// <param name = "_status">Outcome status to record</param>
/// <param name = "_errorMessage">Error message, if any</param>
private void updateExtractionLineStatus(METSalesOrderExtractionStatus _status, str _errorMessage)
{
    METSalesOrderExtractionLine extractionLine = METSalesOrderExtractionLine::find(extractionId, salesId, true);

    if (extractionLine.RecId)
    {
        ttsbegin;
        extractionLine.ExtractionStatus   = _status;
        extractionLine.ErrorMessage       = _errorMessage;
        extractionLine.ProcessEndDateTime = DateTimeUtil::getSystemDateTime();
        extractionLine.update();
        ttscommit;
    }
}

/// <summary>
/// Clears METProcessing once this SO's pick list attempt is done, success or failure.
/// </summary>
/// <param name = "_salesId">Sales order to reset</param>
private void resetProcessingFlag(SalesId _salesId)
{
    SalesTable salesTableLoc;
    ttsbegin;
    select firstonly forupdate salesTableLoc where salesTableLoc.SalesId == _salesId;
    salesTableLoc.skipBusinessEvents(true);
    if (salesTableLoc.RecId && salesTableLoc.METProcessing == NoYes::Yes)
    {
        salesTableLoc.METProcessing = NoYes::No;
        salesTableLoc.doUpdate();
    }
    ttscommit;
}

/// <summary>
/// Lazily builds a SalesUpdateRemain configured for extraction.
/// </summary>
/// <returns>The configured SalesUpdateRemain instance</returns>
private SalesUpdateRemain salesUpdateRemain()
{
    if (salesUpdateRemainInstance == null)
    {
        salesUpdateRemainInstance = SalesUpdateRemain::construct();
        salesUpdateRemainInstance.metParmIsExtraction(true);
    }

    return salesUpdateRemainInstance;
}

/// <summary>
/// Named wrapper around ttsbegin for the picking-list transaction.
/// </summary>
private void ttsBeginTrace()
{
    ttsbegin;
}

/// <summary>
/// Named wrapper around ttscommit for the picking-list transaction.
/// </summary>
private void ttsCommitTrace()
{
    ttscommit;
}

/// <summary>
/// Queues this SO for the async pending-process job (TO creation / deferred picking).
/// </summary>
/// <param name = "_salesId">Sales order to queue</param>
private void insertPendingProcessRecord(SalesId _salesId)
{
    METOrderExtractionPendingProcess pendingRecord;

    ttsbegin;
    pendingRecord.SalesId         = _salesId;
    pendingRecord.Status          = METOrderExtractionPendingProcessStatus::Pending;
    pendingRecord.ActionToPerform = actionToPerform;
    pendingRecord.PickingRouteID  = wmsPickingRoute.PickingRouteID;
    pendingRecord.insert();
    ttscommit;
}

/// <summary>
/// Mirrors reservation + pick list posting onto the intercompany purchase order's sales side.
/// </summary>
private void postIntercompanyPickingList()
{
    PurchTable purchTable_Reference = salesTable.referencePurchTable();

    if ((!purchTable_Reference.RecId && !purchTable_Reference.InterCompanySalesId) || !TradeInterCompany::checkDataAreaAccess(purchTable_Reference.InterCompanyCompanyId))
    {
        return;
    }
    else if (purchTable_Reference.RecId)
    {
        changeCompany(purchTable_Reference.InterCompanyCompanyId)
        {
            METStockReservation::construct(purchTable_Reference.interCompanySalesTable()).processV2();

            this.postPickingListV2(purchTable_Reference.interCompanySalesTable(), false);
        }
    }
}

/// <summary>
/// Reserves qualifying lines, posts the pick list, and falls back to a status-only update
/// when nothing qualifies.
/// </summary>
/// <param name = "_salesTable">The sales order to post</param>
/// <param name = "_pickListOrderedQty">True to pick ordered qty instead of reserved qty</param>
public void postPickingListV2(SalesTable _salesTable, boolean _pickListOrderedQty = false)
{
    #OCCRetryCount
    List qualifyingSalesLineRecIds;

    try
    {
        if (_salesTable.SalesStatus != SalesStatus::Canceled)
        {
            reservedQtyInSalesUnitMap  = new Map(Types::Int64, Types::Real);
            reservedQtyInInventUnitMap = new Map(Types::Int64, Types::Real);

            processExtraction = false;

            this.salesUpdateRemain().parmSkipBusinessEvents(true);

            qualifyingSalesLineRecIds = this.calcQueryV2(_salesTable, _pickListOrderedQty);

            if (processExtraction == true)
            {
                this.ttsBeginTrace();

                this.postPickingListDirect(_salesTable, _pickListOrderedQty, qualifyingSalesLineRecIds);

                TransactionLog::create(TransactionLogType::SalesPickingList, "@SYS50969");

                TaxWorkRegulation::clearRegulation(tableNum(SalesTable), _salesTable.RecId);

                this.ttsCommitTrace();
            }
            else
            {
                if (!_salesTable.METAllowBackOrders && !metSalesTable.InternalCrossDockOrder)
                {
                    this.updateExtractedStatusOnSalesLine(_salesTable);
                }
            }

            if (!_salesTable.InterCompanyOrder)
            {
                this.insertPendingProcessRecord(_salesTable.SalesId);
            }
        }
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                error ("@WAX:UpdateCancelled");
                isError = true;
            }
            else
            {
                retry;
            }
        }
        else
        {
            error ("@WAX:UpdateCancelled");
            isError = true;
        }
    }
    catch(Exception::DuplicateKeyException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                error ("@WAX:UpdateCancelled");
                isError = true;
            }
            else
            {
                retry;
            }
        }
        else
        {
            error ("@WAX:UpdateCancelled");
            isError = true;
        }
    }
    catch
    {
        error ("@WAX:UpdateCancelled");
        isError = true;
    }

    _salesTable.reread();
    _salesTable.selectForUpdate(true);
    _salesTable.metUpdateExtractStatus();
}

/// <summary>
/// Finds lines still eligible for picking, creating an intercompany PO first if required.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
/// <param name = "_pickListOrderedQty">True to consider ordered qty, not just reserved qty</param>
/// <returns>List of qualifying SalesLine RecIds</returns>
private List calcQueryV2(SalesTable _salesTable, boolean _pickListOrderedQty)
{
    SalesLine               salesLine;
    METSalesLine            metSalesLineNotExtracted;
    boolean                 interCompanyPOCreated = false;
    PurchLine                purchLineRef, purchLineRefJoin;
    InventLocation           inventLocationLoc;
    InventDim                inventDim;
    List                     qualifyingSalesLines = new List(Types::Int64);

    while select forupdate salesLine
        where salesLine.SalesId == _salesTable.SalesId
            && salesLine.SalesStatus != SalesStatus::Canceled
        join forupdate metSalesLineNotExtracted
            where metSalesLineNotExtracted.SalesLine == salesLine.RecId
        join inventdim
            where inventDim.inventDimId == salesLine.inventDimId
        join inventLocationLoc
            where inventLocationLoc.InventLocationId == inventDim.inventLocationId &&
            ( metSalesLineNotExtracted.OrderExtractStatus != METOrderExtractStatus::Extracted ||
            ((metSalesTable.InternalCrossDockOrder == true && metSalesLineNotExtracted.OrderExtractStatus == METOrderExtractStatus::Extracted) ||
            (inventLocationLoc.METCSDWarehouse == true && metSalesLineNotExtracted.OrderExtractStatus == METOrderExtractStatus::Extracted)))
        outer join purchLineRefJoin
            where purchLineRefJoin.InventTransId == salesLine.InventRefTransId
    {
        if (purchLineRefJoin.RecId && salesLine.InventRefTransId && salesLine.InventRefType == InventRefType::Purch && !purchLineRefJoin.IsDeleted)
        {
            purchLineRef = purchLineRefJoin;
        }

        if (interCompanyPOCreated == false
            && purchLineRef.RecId == 0
            && InventTable::metGetOSCCode(salesLine.ItemId, inventDim) == METConstants::GroceryOscCode
            && _salesTable.METIntercompanyTransferFulfillment == NoYes::Yes
            && _salesTable.InterCompanyOrigin != InterCompanyOrigin::Derived)
        {
            METSalesOrderProcessHelper::createPOForIntercompanyFulfillment(_salesTable, salesLine);
            interCompanyPOCreated = true;
        }
        else if (purchLineRef.RecId != 0)
        {
            continue;
        }
        else
        {
            SalesQtyReservPhysical reservQtyinSalesUnit;
            SalesQtyReservPhysical reservQtyinInventUnit;

            if (reservedQtyInSalesUnitMap.exists(salesLine.RecId))
            {
                reservQtyinSalesUnit = reservedQtyInSalesUnitMap.lookup(salesLine.RecId);
                reservQtyinInventUnit = reservedQtyInInventUnitMap.lookup(salesLine.RecId);
            }
            else
            {
                container reservedQty = salesLine.metReservedPhysicalInSalesInventUnit();

                reservQtyinSalesUnit = conPeek(reservedQty, 1);
                reservQtyinInventUnit = conPeek(reservedQty, 2);

                reservedQtyInSalesUnitMap.add(salesLine.RecId, reservQtyinSalesUnit);
                reservedQtyInInventUnitMap.add(salesLine.RecId, reservQtyinInventUnit);
            }

            if (_pickListOrderedQty == false && reservQtyinSalesUnit == 0)
            {
                continue;
            }

            processExtraction = true;
            qualifyingSalesLines.addEnd(salesLine.RecId);
        }
    }

    salesTable.skipBusinessEvents(true);
    salesTable.updateBackStatus();

    return qualifyingSalesLines;
}

/// <summary>
/// Marks all non-purchase lines Extracted when nothing qualified for a real pick list.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
public void updateExtractedStatusOnSalesLine(SalesTable _salesTable)
{
    METSalesLine metSalesLine;
    SalesLine    salesLine;

    ttsbegin;

    metSalesLine.skipDataMethods(true);
    metSalesLine.skipBusinessEvents(true);

    while select forupdate metSalesLine
            where metSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted
        exists join salesLine
            where salesLine.SalesId        == _salesTable.SalesId
                && salesLine.SalesStatus   != SalesStatus::Canceled
                && salesLine.InventRefType != InventRefType::Purch
                && salesLine.RecId         == metSalesLine.SalesLine
    {
        metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
        metSalesLine.update();
    }

    ttscommit;
}

/// <summary>
/// Orchestrates picking-route setup, posting each qualifying line, then finalization.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
/// <param name = "_pickListOrderedQty">True to pick ordered qty instead of reserved qty</param>
/// <param name = "_qualifyingSalesLines">Lines to post</param>
protected void postPickingListDirect(SalesTable _salesTable, boolean _pickListOrderedQty, List _qualifyingSalesLines)
{
    boolean      isCSDPrint = csdSalesId != '' && csdSalesId == salesId;
    WMSShipment  wmsShipment;
    Map          pickedQtyMap;

    wmsShipment  = this.preparePickingRoute(_salesTable);
    pickedQtyMap = _salesTable.METAllowBackOrders ? this.buildPickedQtyMap(_salesTable) : new Map(Types::String, Types::Real);

    this.postQualifyingLines(_salesTable, _pickListOrderedQty, _qualifyingSalesLines, wmsShipment, pickedQtyMap);

    this.finalizePickingListPosting(_salesTable, wmsShipment, isCSDPrint);
}

/// <summary>
/// Inserts a new order-pick WMS shipment.
/// </summary>
/// <returns>The created shipment</returns>
private WMSShipment createWMSShipment()
{
    WMSShipment wmsShipment;
    wmsShipment.clear();
    wmsShipment.initTypeOrderPick();
    wmsShipment.skipBusinessEvents(true);
    METGlobal::validateWriteRecordCheck(wmsShipment);
    wmsShipment.insert();
    return wmsShipment;
}

/// <summary>
/// Builds the picking route header for this SO's shipment.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
/// <param name = "_inventLoc">The order's warehouse</param>
/// <param name = "_pickingRouteId">Allocated picking route id</param>
/// <param name = "_wmsShipment">Shipment the route belongs to</param>
private void initWMSPickingRoute(SalesTable _salesTable, InventLocation _inventLoc, WMSPickingRouteID _pickingRouteId, WMSShipment _wmsShipment)
{
    wmsPickingRoute.clear();
    wmsPickingRoute.PickingRouteID                  = _pickingRouteId;
    wmsPickingRoute.ParmId                          = _salesTable.SalesId;
    wmsPickingRoute.Customer                        = _salesTable.CustAccount;
    wmsPickingRoute.DeliveryPostalAddress           = _salesTable.DeliveryPostalAddress;
    wmsPickingRoute.DlvDate                         = _salesTable.ShippingDateConfirmed;
    wmsPickingRoute.DlvModeId                       = _salesTable.DlvMode;
    wmsPickingRoute.DlvTermId                       = _salesTable.DlvTerm;
    wmsPickingRoute.ExpeditionStatus                = WMSExpeditionStatus::Activated;
    wmsPickingRoute.InventLocationId                = _salesTable.InventLocationId;
    wmsPickingRoute.PrintMgmtSiteId                 = _inventLoc.InventSiteId;
    wmsPickingRoute.ShipmentId                      = _wmsShipment.ShipmentId;
    wmsPickingRoute.ShipmentType                    = WMSShipmentType::OrderPick;
    wmsPickingRoute.TransRefId                      = _salesTable.SalesId;
    wmsPickingRoute.TransType                       = InventTransType::Sales;
    wmsPickingRoute.DeliveryName                    = _salesTable.DeliveryName;
    wmsPickingRoute.METTransferOrderPickingRouteId  = '';
    wmsPickingRoute.METExternalInvoicedSO           = NoYes::No;
    wmsPickingRoute.InterCompanyPosted              = _salesTable.InterCompanyOrigin != InterCompanyOrigin::Source ? NoYes::Yes : NoYes::No;
    wmsPickingRoute.skipBusinessEvents(true);
    METGlobal::validateWriteRecordCheck(wmsPickingRoute);
    wmsPickingRoute.insert();
}

/// <summary>
/// Sums already-picked qty per InventTransId, used for back-order line status.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
/// <returns>Map(InventTransId -> picked qty)</returns>
private Map buildPickedQtyMap(SalesTable _salesTable)
{
    Map             pickedQtyMap = new Map(Types::String, Types::Real);
    WMSOrderTrans   wmsOrderTransPre;
    SalesLine       salesLineJoin;

    while select sum(Qty), InventTransId from wmsOrderTransPre
      group by wmsOrderTransPre.InventTransId
      exists join salesLineJoin
          where salesLineJoin.SalesId       == _salesTable.SalesId
             && salesLineJoin.InventTransId == wmsOrderTransPre.InventTransId
    {
        pickedQtyMap.add(wmsOrderTransPre.InventTransId, wmsOrderTransPre.Qty);
    }

    return pickedQtyMap;
}

/// <summary>
/// Resolves the qty to pick now: ordered qty (ordered-mode) or reserved qty (default).
/// </summary>
/// <param name = "_salesLine">The line</param>
/// <param name = "_pickListOrderedQty">True to use ordered qty</param>
/// <returns>Qty to pick now, in inventory unit</returns>
private InventQty calcInventNow(SalesLine _salesLine, boolean _pickListOrderedQty)
{
    InventQty sourceQty;

    if (_pickListOrderedQty)
    {
        sourceQty = _salesLine.SalesQty;

        UnitOfMeasureSymbol inventUnit = _salesLine.inventTable().inventUnitId();

        if (_salesLine.SalesUnit == inventUnit)
        {
            return sourceQty;
        }

        sourceQty = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                                                                _salesLine.ItemId,
                                                                                _salesLine.InventDimId,
                                                                                sourceQty,
                                                                                _salesLine.SalesUnit,
                                                                                inventUnit,
                                                                                NoYes::No,
                                                                                NoYes::No);
    }
    else
    {
        sourceQty = this.getSalesLineReservPhysicalInInventUnit(_salesLine);
    }

    return sourceQty;
}

/// <summary>
/// Cached lookup of a line's reserved qty in inventory unit.
/// </summary>
/// <param name = "_salesLine">The line</param>
/// <returns>Reserved qty in inventory unit</returns>
public SalesQtyReservPhysical getSalesLineReservPhysicalInInventUnit(SalesLine _salesLine)
{
    SalesQtyReservPhysical reservPhysical;

    if (reservedQtyInInventUnitMap.exists(_salesLine.RecId))
    {
        reservPhysical = reservedQtyInInventUnitMap.lookup(_salesLine.RecId);
    }
    else
    {
        container reservedQty = _salesLine.metReservedPhysicalInSalesInventUnit();

        SalesQtyReservPhysical reservQtyinSalesUnit = conPeek(reservedQty, 1);
        SalesQtyReservPhysical reservQtyinInventUnit = conPeek(reservedQty, 2);

        reservedQtyInSalesUnitMap.add(_salesLine.RecId, reservQtyinSalesUnit);
        reservedQtyInInventUnitMap.add(_salesLine.RecId, reservQtyinInventUnit);

        reservPhysical = reservQtyinInventUnit;
    }

    return reservPhysical;
}

/// <summary>
/// Extracted if fully picked or back orders aren't allowed; otherwise stays Open.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
/// <param name = "_salesLine">The line</param>
/// <param name = "_shipQty">Qty just shipped for this line</param>
/// <param name = "_pickedQtyMap">Already-picked qty per InventTransId</param>
/// <returns>Resolved extract status for the line</returns>
private METOrderExtractStatus resolveLineStatus(SalesTable _salesTable, SalesLine _salesLine, InventQty _shipQty, Map _pickedQtyMap)
{
    if (!_salesTable.METAllowBackOrders || metSalesTable.InternalCrossDockOrder)
    {
        return METOrderExtractStatus::Extracted;
    }

    InventQty totalPicked = (_pickedQtyMap.exists(_salesLine.InventTransId)
      ? _pickedQtyMap.lookup(_salesLine.InventTransId)
      : 0) + _shipQty;

    return (totalPicked == _salesLine.QtyOrdered)
      ? METOrderExtractStatus::Extracted
      : METOrderExtractStatus::Open;
}

/// <summary>
/// Persists the resolved line status.
/// </summary>
/// <param name = "_salesLineRecId">Line to update</param>
/// <param name = "_lineStatus">Status to set</param>
private void updateMETSalesLineStatus(RefRecId _salesLineRecId, METOrderExtractStatus _lineStatus)
{
    METSalesLine metSalesLineUpd = METSalesLine::find(_salesLineRecId, true);

    if (metSalesLineUpd.RecId)
    {
        metSalesLineUpd.OrderExtractStatus = _lineStatus;
        metSalesLineUpd.skipBusinessEvents(true);
        metSalesLineUpd.update();
    }
}

/// <summary>
/// Bulk markup/deliver-now/status cleanup after all lines are posted.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
private void batchUpdateAfterLoop(SalesTable _salesTable)
{
    SalesLine   salesLineJoin;
    MarkupTrans markupTransBatch;
    markupTransBatch.skipDataMethods(true);
    markupTransBatch.skipBusinessEvents(true);

    update_recordset markupTransBatch
      setting DocumentStatus = DocumentStatus::PickingList
      where   markupTransBatch.TransTableId   == tableNum(SalesLine)
           && markupTransBatch.Keep           == NoYes::No
           && markupTransBatch.DocumentStatus != DocumentStatus::PickingList
           && markupTransBatch.DocumentStatus != DocumentStatus::PackingSlip
      exists join salesLineJoin
          where salesLineJoin.SalesId    == _salesTable.SalesId
             && salesLineJoin.SalesStatus != SalesStatus::Canceled
             && salesLineJoin.RecId       == markupTransBatch.TransRecId;

    SalesLine salesLineDeliverNow;

    salesLineDeliverNow.skipBusinessEvents(true);

    while select forupdate salesLineDeliverNow
        where salesLineDeliverNow.SalesId    == _salesTable.SalesId
           && salesLineDeliverNow.SalesStatus != SalesStatus::Canceled
    {
        salesLineDeliverNow.SalesDeliverNow       = 0;
        salesLineDeliverNow.InventDeliverNow      = 0;
        salesLineDeliverNow.PdsCWInventDeliverNow = 0;
        salesLineDeliverNow.doUpdate();
    }

    if (!_salesTable.METAllowBackOrders)
    {
        METSalesLine metSalesLineBatch;
        SalesLine    salesLineStatus;

        metSalesLineBatch.skipDataMethods(true);
        metSalesLineBatch.skipBusinessEvents(true);

        update_recordset metSalesLineBatch
            setting OrderExtractStatus = METOrderExtractStatus::Extracted
        exists join salesLineStatus
            where salesLineStatus.SalesId       == _salesTable.SalesId
                && salesLineStatus.SalesStatus   != SalesStatus::Canceled
                && salesLineStatus.InventRefType != InventRefType::Purch
                && salesLineStatus.RecId         == metSalesLineBatch.SalesLine;
    }
}

/// <summary>
/// Activates the route (or completes it, per SalesParameters setting).
/// </summary>
private void activatePickingRoute()
{
    WMSPickRouteStatusOnUpdate pickRouteStatus = SalesParameters::find().PickRouteStatusOnUpdate;

    if (pickRouteStatus != WMSPickRouteStatusOnUpdate::completed)
    {
        WMSOrderTrans wmsOrderTransBatch;
        wmsOrderTransBatch.skipDataMethods(true);
        wmsOrderTransBatch.skipBusinessEvents(true);

        update_recordset wmsOrderTransBatch
          setting ExpeditionStatus = WMSExpeditionStatus::Activated
          where wmsOrderTransBatch.RouteId == wmsPickingRoute.PickingRouteID;

        wmsPickingRoute.selectForUpdate(true);
        wmsPickingRoute.ExpeditionStatus   = WMSExpeditionStatus::Activated;
        wmsPickingRoute.ActivationDateTime = DateTimeUtil::getSystemDateTime();
        wmsPickingRoute.skipBusinessEvents(true);
        wmsPickingRoute.update();

        WMSShipment wmsShipmentActivate = wmsPickingRoute.wmsShipment(true);
        if (wmsShipmentActivate.RecId)
        {
            wmsShipmentActivate.setStatus(NoYes::Yes, NoYes::No);
        }
    }
    else
    {
        wmsPickingRoute.skipBusinessEvents(true);
        wmsPickingRoute.updateRoute(pickRouteStatus);
    }
}

/// <summary>
/// Links the picking route back to the SO.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
private void createPickingRouteLink(SalesTable _salesTable)
{
    WMSPickingRouteLink wmsPickingRouteLink;
    wmsPickingRouteLink.clear();
    wmsPickingRouteLink.initFromSalesTable(_salesTable);
    wmsPickingRouteLink.initFromWMSPickingRoute(wmsPickingRoute);
    wmsPickingRouteLink.skipBusinessEvents(true);
    METGlobal::validateWriteRecordCheck(wmsPickingRouteLink);
    wmsPickingRouteLink.insert();
}

/// <summary>
/// Updates document/back-order/sales-type status on the SO.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
private void finalizeSalesTableStatus(SalesTable _salesTable)
{
    SalesTable salesTableUpd = SalesTable::find(_salesTable.SalesId, true);
    salesTableUpd.skipBusinessEvents(true);
    salesTableUpd.updateDocumentStatus(DocumentStatus::PickingList);
    salesTableUpd.updateBackStatus();
    salesTableUpd.updateSalesType();

    Markup::updateMarkupAsPosted(_salesTable, DocumentStatus::PickingList);
}

/// <summary>
/// Marks the WMS shipment Picked, backfilling location if needed.
/// </summary>
/// <param name = "_wmsShipment">Shipment to finalize</param>
private void finalizeShipment(WMSShipment _wmsShipment)
{
    _wmsShipment.selectForUpdate(true);
    _wmsShipment.reread();
    _wmsShipment.skipBusinessEvents(true);
    if (!_wmsShipment.InventLocationId)
    {
        WMSPickingRoute wmsPickingRouteForShipment;
        select firstonly wmsPickingRouteForShipment
          where wmsPickingRouteForShipment.ShipmentId == _wmsShipment.ShipmentId;

        _wmsShipment.InventLocationId = wmsPickingRouteForShipment.InventLocationId;
        _wmsShipment.InventSiteId     = InventLocation::find(wmsPickingRouteForShipment.InventLocationId).InventSiteId;
    }

    _wmsShipment.Status               = WMSShipmentStatus::Picked;
    _wmsShipment.PickExpeditionStatus = WMSExpeditionStatus::Started;
    _wmsShipment.doUpdate();
}

/// <summary>
/// Propagates Extracted status back to the originating intercompany sales line.
/// </summary>
/// <param name = "_salesLine">The derived intercompany line</param>
private void updateIntercompanySalesLine(SalesLine _salesLine)
{
    if (_salesLine.isDerivedIntercompanyLine() && _salesLine.InterCompanyInventTransId)
    {
        changecompany(_salesLine.salesTable().InterCompanyCompanyId)
        {
            PurchLine purchLine = PurchLine::findInventTransId(_salesLine.InterCompanyInventTransId);
            if (purchLine.InterCompanyInventTransId && purchLine.ItemRefType == InventRefType::Sales)
            {
                SalesLine origSalesLine = SalesLine::findInventTransId(purchLine.InventRefTransId);
                METSalesLine metICSalesLine = METSalesLine::find(origSalesLine.RecId, true);

                if (metICSalesLine)
                {
                    metICSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                    metICSalesLine.skipBusinessEvents(true);
                    metICSalesLine.doUpdate();
                }

                origSalesLine.salesTable(true).metUpdateExtractStatus();
            }
        }
    }
}

/// <summary>
/// Orchestrates the End task: CSD wave event, shipment cleanup, completion check, header finalize.
/// </summary>
protected void runFinalTask()
{
    str     failedSalesIds;
    boolean allCompleted;

    this.triggerCsdWaveEvent();

    METSalesOrderShipmentLoadHeader::cleanShipmentIfNoLines(shipmentIdList);

    [allCompleted, failedSalesIds] = this.validateAllLinesCompleted();

    this.finalizeExtractionHeader(allCompleted);

    if (!allCompleted)
    {
        warning(strFmt("@MET:METExtractionPartiallyCompleted", extractionId, failedSalesIds));
    }
}

/// <summary>
/// Parameters are always set via code, never loaded from SysLastValue.
/// </summary>
/// <returns>Always false</returns>
public boolean allowSaveLast()
{
    return false;
}

/// <summary>
/// Per-role task caption: pick list for a SalesId, or finalize/export.
/// </summary>
/// <returns>The caption for this task instance</returns>
public ClassDescription caption()
{
    if (batchIdentifier == this.finalTaskIdentifier())
    {
        return "@MET:METCaptionFinalizeExport";
    }
    else if (salesId)
    {
        return strFmt("@MET:METCaptionPickList", salesId);
    }

    return super();
}

/// <summary>
/// SOExtractUpdateStatusOnly: marks the SO and its lines Extracted without posting a pick list.
/// </summary>
private void updateStatusOnlyForSalesTable()
{
    METSalesLine    metSalesLine;
    SalesLine       salesLineUpdate;

    ttsbegin;
    salesTable.reread();
    salesTable.selectForUpdate(true);
    salesTable.skipDatabaseLog(true);
    salesTable.skipDataMethods(true);
    salesTable.SkipUpdate = true;
    salesTable.SkipLineUpdate = true;
    salesTable.METOrderExtractStatus = METOrderExtractStatus::Extracted;
    salesTable.METOrderExtractDateTime = DateTimeUtil::getSystemDateTime();
    salesTable.update();

    update_recordset metSalesLine
        setting OrderExtractStatus = METOrderExtractStatus::Extracted
            exists join salesLineUpdate
                where salesLineUpdate.RecId == metSalesLine.SalesLine &&
                    salesLineUpdate.SalesId == salesTable.SalesId;

    ttscommit;

    info(strFmt("@MET:SOExtractionUpdate", salesTable.SalesId));
}

/// <summary>
/// Allocates the picking route id, creates the WMS shipment, and initializes the picking route header.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
/// <returns>The created WMS shipment</returns>
private WMSShipment preparePickingRoute(SalesTable _salesTable)
{
    InventLocation     inventLoc      = InventLocation::find(_salesTable.InventLocationId);
    WMSPickingRouteID  pickingRouteId = NumberSeq::newGetNum(WMSParameters::numRefWMSPickingRouteId()).num();
    WMSShipment        wmsShipment    = this.createWMSShipment();

    this.initWMSPickingRoute(_salesTable, inventLoc, pickingRouteId, wmsShipment);

    return wmsShipment;
}

/// <summary>
/// Posts WMS pick quantities for each qualifying line and resolves its back-order status.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
/// <param name = "_pickListOrderedQty">True to pick ordered qty instead of reserved qty</param>
/// <param name = "_qualifyingSalesLines">Lines to post</param>
/// <param name = "_wmsShipment">Shipment to post lines against</param>
/// <param name = "_pickedQtyMap">Already-picked qty per InventTransId</param>
private void postQualifyingLines(SalesTable _salesTable, boolean _pickListOrderedQty, List _qualifyingSalesLines, WMSShipment _wmsShipment, Map _pickedQtyMap)
{
    boolean         useQualityManagement = InventParameters::find().UseQualityManagement;
    ListEnumerator  le = _qualifyingSalesLines.getEnumerator();
    SalesLine       salesLine;

    while (le.moveNext())
    {
        select firstonly forupdate salesLine
            where salesLine.RecId == le.current();

        if (salesLine)
        {
            boolean         cwItem = PdsGlobal::pdsIsCWItem(salesLine.ItemId);
            InventQty       inventNow   = this.calcInventNow(salesLine, _pickListOrderedQty);

            if (!inventNow)
            {
                continue;
            }

            if (useQualityManagement)
            {
                InventQualityManagementBlockHandler::blockSalesPickingList(salesLine);
            }

            PdsCWInventQty cwQty = cwItem ? salesLine.pdsCWRemainInventPhysical : 0;

            WMSOrder  wmsOrder  = WMSOrderCreate::createOrUpdateWMSOrder(InventMovement::construct(salesLine),
                                                                        -inventNow,
                                                                        WMSOrderType::OrderPick,
                                                                        '',
                                                                        -cwQty);

            InventQty shipQty   = min(inventNow, wmsOrder.qtyNoShipment);

            cwQty = cwItem ? min(cwQty, wmsOrder.PdsCWQtyNoShipment) : 0;

            wmsOrder.updateShipment(_wmsShipment,
                shipQty,
                wmsPickingRoute.PickingRouteID,
                true,
                cwQty);

            if (useQualityManagement)
            {
                InventQualityManagementCreateHandler::createSalesPickingListAfterPost(salesLine, inventNow, cwQty);
            }

            if (_salesTable.InterCompanyCompanyId)
            {
                SalesLineType::construct(salesLine).interCompanyResetDeliverNow();
            }

            if (_salesTable.METAllowBackOrders)
            {
                METOrderExtractStatus lineStatus = this.resolveLineStatus(_salesTable, salesLine, shipQty, _pickedQtyMap);
                this.updateMETSalesLineStatus(salesLine.RecId, lineStatus);
            }

            this.updateIntercompanySalesLine(salesLine);
        }
    }
}

/// <summary>
/// Bulk cleanup, route activation/link, SO/shipment finalize, WMS trans populate, and shipment load.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
/// <param name = "_wmsShipment">Shipment that was posted</param>
/// <param name = "_isCSDPrint">True to show the CSD ordered-qty info message instead of the standard one</param>
private void finalizePickingListPosting(SalesTable _salesTable, WMSShipment _wmsShipment, boolean _isCSDPrint)
{
    this.batchUpdateAfterLoop(_salesTable);

    this.activatePickingRoute();
    this.createPickingRouteLink(_salesTable);
    this.finalizeSalesTableStatus(_salesTable);
    this.finalizeShipment(_wmsShipment);

    METWMSOrderTransPickListFieldsPopulator::updateMETWMSOrderTrans(wmsPickingRoute.pickingRouteID);

    METOrderShipmentLoadCreation::construct(METOrderTransactionType::SalesOrder, _salesTable.SalesId)
      .createShippmentLoad(true, false);

    if (!_isCSDPrint)
    {
        info(strFmt("@MET:PickListForReservedQty", _salesTable.SalesId));
    }
    else
    {
        info(strFmt("@MET:SOPickListForOrderQty", _salesTable.SalesId));
    }
}

/// <summary>
/// Fires the wave-generated business event for CSD orders, if this run had any.
/// </summary>
private void triggerCsdWaveEvent()
{
    if (csdSalesId && csdGuid && conLen(csdSalesOrderList) > 0 && csdOrderExtractDateTime)
    {
        METWaveTable metWaveTable = METWaveTable::findByOrderExtractDateTimeAndGuid(csdOrderExtractDateTime, csdGuid);

        if (metWaveTable)
        {
            metWaveTable.triggerWaveGeneratedBusinessEvent(csdSalesOrderList);
        }
    }
}

/// <summary>
/// Checks every extraction line for this ExtractionId.
/// </summary>
/// <returns>Container [allCompleted, failedSalesIds]</returns>
private container validateAllLinesCompleted()
{
    METSalesOrderExtractionLine line;
    boolean                     allCompleted = true;
    str                         failedSalesIds;

    while select line
        where line.ExtractionId == extractionId
    {
        if (line.ExtractionStatus != METSalesOrderExtractionStatus::Completed)
        {
            allCompleted    = false;
            failedSalesIds += line.SalesId + ' ';
        }
    }

    return [allCompleted, failedSalesIds];
}

/// <summary>
/// Flips ExtractionStatus to Completed/PartiallyCompleted; Completed triggers the export DataEventHandler.
/// </summary>
/// <param name = "_allCompleted">True if every extraction line completed successfully</param>
private void finalizeExtractionHeader(boolean _allCompleted)
{
    METSalesOrderExtractionTable header;

    ttsbegin;
    header = METSalesOrderExtractionTable::find(extractionId, true);

    if (header.RecId)
    {
        header.ExtractionStatus = _allCompleted
            ? METSalesOrderExtractionStatus::Completed
            : METSalesOrderExtractionStatus::PartiallyCompleted;
        header.update();

        // Send the file.
        if (header.ExtractionStatus == METSalesOrderExtractionStatus::Completed)
        {
            DEVIntegExportDocumentsLog::exportRecordList(DEVIntegExportRecordList::constructFromRecord(header, classStr(METSalesOrderExtractionExportIntegration)));
        }
    }
    ttscommit;
}
